let patched = 0;
const missing = [];
for (const card of deck.cards) {
  const id = card.arcana_id;
  if (!STORY_ES[id] || !RESUMEN_EN[id] || !SOMBRA_EN[id]) { missing.push(id); continue; }
  // Mover el ES original a *_es solo la primera vez (idempotente).
  if (card.deck_resumen_es === undefined) card.deck_resumen_es = card.deck_resumen;
  if (card.deck_sombra_es === undefined) card.deck_sombra_es = card.deck_sombra;
  // Fijar base EN + traducción ES de la historia (deck_story EN se conserva).
  card.deck_resumen = RESUMEN_EN[id];
  card.deck_sombra = SOMBRA_EN[id];
  card.deck_story_es = STORY_ES[id];
  patched++;
}

if (missing.length) {
  throw new Error(`Faltan traducciones para: ${missing.join(", ")}`);
}

writeFileSync(path, JSON.stringify(deck, null, 2) + "\n", "utf8");
console.log(`OK · Yōkai bilingüe aplicado a ${patched} cartas (deck_story_es + deck_resumen/sombra EN+ES)`);
